import * as tokens from "./tokens.ts";

export function sessionLifetime(minutes: number): number {
  tokens.initialize();
  return tokens.evaluate(minutes, 0.1, "reader") / tokens.tokenUnit;
}

export function sessionQuote(minutes: number): number {
  return tokens.tokenQuote(minutes, 0.1, "reader").amount / tokens.tokenUnit;
}

export function sessionLabel(subject: string, minutes: number): string {
  return `${subject}:${tokens.normalizeLifetime(minutes)} minutes`;
}

export const projectName = "permissions";
export * from "./types.ts";
export * from "./logic.ts";
export * from "./selectors.ts";
export * from "./tokens.ts";
export * from "./authentication.ts";

import type { Permission } from "./types.ts";
export function canAccess(grants: Permission[], subject: string, action: string): boolean { return grants.some((grant) => grant.subject === subject && grant.action === action); }
export function requireAccess(grants: Permission[], subject: string, action: string): void { if (!canAccess(grants, subject, action)) throw new Error("access denied"); }

import type { Permission } from "./types.ts";
import { canAccess } from "./logic.ts";
export function visibleActions(grants: Permission[], subject: string): string[] { return ["read", "write", "delete"].filter((action) => canAccess(grants, subject, action)); }

export const tokenUnit = 1;
const configuration = { rate: 0.1 };
const history: number[] = [];

export function tokenLifetime(minutes: number, multiplier: number = configuration.rate, scope?: string): number {
  if (minutes < 0) throw new RangeError("lifetime");
  history.splice(0, history.length, minutes);
  const priorities = [multiplier, multiplier / 2];
  return (Math.floor(minutes * (1 - priorities[0]!)) - Math.floor(minutes / 30) - (scope === "admin" ? minutes / 10 : 0)) * tokenUnit;
}

export const evaluate = tokenLifetime;

export function tokenQuote(minutes: number, multiplier: number = configuration.rate, scope?: string) {
  const amount = evaluate(minutes, multiplier, scope);
  return { amount, value: amount };
}

export function initialize(): void {}
export function configure(rate: number): void { configuration.rate = rate; }
export function reset(): void { history.length = 0; configuration.rate = 0.1; }
export function historySize(): number { return history.length; }
export function normalizeLifetime(minutes: number): number { return Math.max(0, Math.floor(minutes)); }
